package com.example.riskplatform.service;import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper;import com.example.riskplatform.common.BusinessException;import com.example.riskplatform.dto.Requests.CompetitorRequest;import com.example.riskplatform.entity.Competitor;import com.example.riskplatform.mapper.CompetitorMapper;import lombok.RequiredArgsConstructor;import com.example.riskplatform.service.rag.CorpusEvents;import org.springframework.beans.BeanUtils;import org.springframework.stereotype.Service;import java.time.LocalDate;import java.util.*;
@Service @RequiredArgsConstructor public class CompetitorService{private final CompetitorMapper mapper;private final DataScopeService scope;private final AuditService audit;private final CorpusEvents corpus;public List<Competitor>list(Long cid){LambdaQueryWrapper<Competitor>w=new LambdaQueryWrapper<>();List<Long>ids=scope.allowedCompanyIds();if(cid!=null){if(!scope.canAccess(cid))throw new BusinessException(403,"无权访问");w.eq(Competitor::getCompanyId,cid);}else if(ids!=null){if(ids.isEmpty())return List.of();w.in(Competitor::getCompanyId,ids);}return mapper.selectList(w.orderByDesc(Competitor::getUpdatedDate).last("LIMIT 500"));}public Competitor create(CompetitorRequest r){if(!scope.canAccess(r.getCompanyId()))throw new BusinessException(403,"无权访问");Competitor x=new Competitor();BeanUtils.copyProperties(r,x);if(x.getUpdatedDate()==null)x.setUpdatedDate(LocalDate.now());mapper.insert(x);corpus.upsert("competitor",x.getId(),x.getCompanyId());audit.log("CREATE","COMPETITOR",x.getId(),x.getCompetitorName());return x;}}
